<?php
namespace App\Services\DevOps;
final class EnvironmentComparisonService {public function __construct(private ReleaseService $releases){}public function compare():array{$stage=$this->releases->active('stage');$production=$this->releases->active('production');if(!$stage||!$production)return['status'=>'unknown','stage'=>$stage,'production'=>$production,'message'=>'Falta una release activa para determinar la relación.'];if($stage->files_fingerprint&&$production->files_fingerprint&&$stage->files_fingerprint!==$production->files_fingerprint&&$stage->package_sha256===$production->package_sha256)return['status'=>'drift_detected','stage'=>$stage,'production'=>$production,'message'=>'El mismo paquete presenta fingerprints distintos.'];if($stage->commit_hash&&hash_equals((string)$stage->commit_hash,(string)$production->commit_hash))return['status'=>'synchronized','stage'=>$stage,'production'=>$production,'message'=>'Los commits coinciden.'];if($stage->package_sha256&&hash_equals($stage->package_sha256,$production->package_sha256))return['status'=>'synchronized','stage'=>$stage,'production'=>$production,'message'=>'Los paquetes SHA-256 coinciden.'];return['status'=>'diverged','stage'=>$stage,'production'=>$production,'message'=>'Las releases difieren; no hay evidencia Git suficiente para calcular ahead/behind.'];}}
